  rowOf(FA, kinds, 0);
  let band = KINDS[kinds[0]].depth + 1;
  if (rows === 2) {
    // the facing row: its counter edge depth(deep)+wall+aisle+wall+depth(shallow) back, deep behind shallow
    const deepD = KINDS.deep.depth, shD = KINDS.shallow.depth;
    band = deepD + 1 + aisle + 1 + shD;
    const back = FA.p(kinds.length * BAY, 0, -(band - 1));                       // seen from the far street, u runs the other way
    const FB = frame(OPPOSITE[face], back);
    const kindsB = [...kinds].reverse().map((t) => (t === "deep" ? "shallow" : "deep"));
    rowOf(FB, kindsB, 1);
